<?php
/** Same-page email settings, sanitized template editing and sample-only preview. */
if(!defined('ABSPATH'))exit;
function crmp_sanitize_email_template($id,$raw){
 $defaults=crmp_email_defaults($id);$out=array();
 foreach($defaults as $key=>$default){$value=$raw[$key]??$default;if($key==='show_note'){$out[$key]=!empty($value);continue;}if(!is_scalar($value))$value=$default;$value=crmp_text_limit((string)$value,in_array($key,array('message','additional'),true)?20000:2000);$out[$key]=in_array($key,array('message','additional'),true)?wp_kses_post($value):sanitize_text_field($value);}
 return crmp_email_required_defaults($id,$out);
}
function crmp_save_email_settings($input){
 if(!current_user_can('manage_woocommerce'))return new WP_Error('crmp_forbidden','Not allowed.');
 $addresses=isset($input['admin_emails'])&&is_scalar($input['admin_emails'])?array_unique(array_map('trim',explode(',',(string)$input['admin_emails']))):array();
 if(!$addresses||count($addresses)>20)return new WP_Error('crmp_recipients','Enter between 1 and 20 valid admin email addresses, separated by commas.');
 foreach($addresses as $email)if(strlen($email)>254||!is_email($email))return new WP_Error('crmp_recipients','Settings were not saved. Check the admin email addresses.');
 $raw=isset($input['templates'])&&is_string($input['templates'])?json_decode($input['templates'],true):null;if(!is_array($raw))return new WP_Error('crmp_templates','Settings were not saved. Reload the page and retry.');
 $templates=array();$enabled=array();foreach(crmp_email_catalog() as $id=>$type){if(!isset($raw[$id])||!is_array($raw[$id]))return new WP_Error('crmp_templates','An email template is missing. Reload the page before saving.');$templates[$id]=crmp_sanitize_email_template($id,$raw[$id]);$enabled[$id]=!empty($input['enabled'][$id]);}
 $settings=array('admin_emails'=>implode(', ',$addresses),'delay'=>max(1,min(10080,absint($input['delay']??15))),'enabled'=>$enabled,'templates'=>$templates);update_option('crmp_email_settings',$settings,false);return $settings;
}
function crmp_proof_policy_settings($context='checkout'){
 $order=$context==='order';$name=$order?'order_proof_policy':'proof_policy';
 $raw=$order?get_option('crmp_order_proof_policy',crmp_default_proof_policy()):crmp_proof_policy();
 $policy=is_array($raw)?crmp_validate_proof_policy($raw):crmp_default_proof_policy();if(is_wp_error($policy))$policy=crmp_default_proof_policy();
 $labels=array('screenshot'=>'Payment screenshot','reference'=>'Transaction reference','date'=>'Payment date','note'=>'Customer note','confirmation'=>'Payment confirmation checkbox');
 echo '<div class="crmp-proof-policy" data-policy-context="'.esc_attr($context).'"><h3>'.($order?'Order-page update fields':'Checkout fields').'</h3><p>Choose visible and required fields. At least one of Screenshot or Reference must remain enabled. If both are optional, each proof submission must still supply one. Disabled fields cannot be required.</p><table class="widefat striped"><thead><tr><th>Field</th><th>Enabled</th><th>Required</th></tr></thead><tbody>';
 foreach($labels as $key=>$label){
  echo '<tr data-proof-field="'.esc_attr($key).'"><th scope="row">'.esc_html($label).'</th><td><label><input type="checkbox" class="crmp-proof-enabled" name="'.esc_attr($name).'['.esc_attr($key).'_enabled]" value="1" '.checked($policy[$key.'_enabled'],true,false).'> Show</label></td><td><label><input type="checkbox" class="crmp-proof-required" name="'.esc_attr($name).'['.esc_attr($key).'_required]" value="1" '.checked($policy[$key.'_required'],true,false).(!$policy[$key.'_enabled']?' disabled':'').'> Required</label></td></tr>';
 }
 echo '</tbody></table><div class="crmp-proof-recommendation"><p><strong>Recommended: mark at least one enabled payment-proof field as Required.</strong></p><p>You control the Required options. If Screenshot and Reference are both optional, each proof submission must still contain at least one of them. Mandatory checkout proof can be disabled separately; orders without proof remain unpaid/On hold.</p><p>For reference + date without a screenshot, make Reference required and Screenshot optional or disabled. Disabled fields are not collected; existing history is retained.</p></div><p class="crmp-proof-optional-warning crmp-proof-recommendation" role="status"'.($policy['screenshot_enabled']&&$policy['reference_enabled']&&!$policy['screenshot_required']&&!$policy['reference_required']?'':' hidden').'>Both proof fields are optional individually. A customer must still supply at least one enabled proof field when submitting proof. Mandatory checkout proof is controlled separately above.</p><p class="crmp-proof-policy-warning" role="alert" hidden>Enable at least one of Screenshot or Reference before saving.</p></div>';
}
function crmp_email_settings_page(){
 if(!current_user_can('manage_woocommerce'))return;
 $notice='';$error=false;
 if(isset($_POST['crmp_save_general'])){
  check_admin_referer('crmp_save_general');
  // phpcs:ignore WordPress.Security.ValidatedSanitizedInput.InputNotSanitized -- Whole form is whitelisted and sanitized by crmp_save_email_settings.
  $policy=crmp_validate_proof_policy(isset($_POST['proof_policy'])&&is_array($_POST['proof_policy'])?wp_unslash($_POST['proof_policy']):array());
  $same=!empty($_POST['order_proof_same']);
  // phpcs:ignore WordPress.Security.ValidatedSanitizedInput.InputNotSanitized -- crmp_validate_proof_policy whitelists known boolean keys and clears hidden requirements.
  $order_policy=$same?null:crmp_validate_proof_policy(isset($_POST['order_proof_policy'])&&is_array($_POST['order_proof_policy'])?wp_unslash($_POST['order_proof_policy']):array());
  $result=is_wp_error($policy)?$policy:(is_wp_error($order_policy)?$order_policy:crmp_save_email_settings(wp_unslash($_POST)));
  if(is_wp_error($result)){$notice=$result->get_error_message();$error=true;}else{update_option('crmp_require_checkout_proof',isset($_POST['require_checkout_proof'])&&sanitize_text_field(wp_unslash($_POST['require_checkout_proof']))==='1'?'yes':'no',false);update_option('crmp_proof_policy',$policy,false);update_option('crmp_order_proof_same',$same?'yes':'no',false);if(!$same)update_option('crmp_order_proof_policy',$order_policy,false);update_option('crmp_max_upload_mb',max(1,min(8,absint($_POST['max_mb']??5))));$update_limit=isset($_POST['proof_update_limit'])&&is_scalar($_POST['proof_update_limit'])?(int)$_POST['proof_update_limit']:crmp_proof_update_limit();update_option('crmp_proof_update_limit',max(1,min(10,$update_limit)),false);$notice='Settings and email templates saved.';}
 }
 $c=crmp_email_config();wp_enqueue_script('crmp-email-settings',CRMP_URL.'assets/email-settings.js',array('jquery'),crmp_asset_version('assets/email-settings.js'),true);
 wp_localize_script('crmp-email-settings','crmpEmails',array('ajaxUrl'=>admin_url('admin-ajax.php'),'nonce'=>wp_create_nonce('crmp_email_settings'),'templates'=>$c['templates']));
 echo '<div class="wrap crmp-wrap crmp-email-settings"><h1>CardRaabta Settings</h1>';
 if($notice)echo '<div class="notice '.($error?'notice-error':'notice-success').'" role="status"><p>'.esc_html($notice).'</p></div>';
 echo '<form method="post" id="crmp-email-settings-form">';wp_nonce_field('crmp_save_general');
 echo '<input type="hidden" id="crmp-email-templates" name="templates" value="'.esc_attr(wp_json_encode($c['templates'])).'"><section class="crmp-panel"><h2>Payment proof</h2><p>Transaction ID or screenshot is required. Payments are verified manually.</p><label>Maximum screenshot size (MB): <input type="number" name="max_mb" min="1" max="8" value="'.esc_attr(get_option('crmp_max_upload_mb',5)).'"></label><p><label for="crmp-proof-update-limit">Maximum proof updates between admin reviews: <input type="number" id="crmp-proof-update-limit" name="proof_update_limit" min="1" max="10" step="1" required value="'.absint(crmp_proof_update_limit()).'"></label></p><p class="description">Default 3; choose 1–10 replacement submissions after the initial proof. Completed rejection resets used attempts; verification closes submissions. Changing this limit does not reset used attempts.</p></section>';
 echo '<section class="crmp-panel"><h2>Payment proof field settings</h2><p><label><input type="checkbox" name="require_checkout_proof" value="1" '.checked(crmp_checkout_proof_required(),true,false).'> <strong>Require payment proof before placing an order</strong></label></p><p class="description">Enabled by default. When disabled, customers may leave all proof fields empty and submit proof later; orders stay unpaid/On hold. Any submitted proof must satisfy the configured field rules.</p><p>Default: screenshot and payment date only, both required. Order forms stay collapsed until the customer chooses to submit or update proof.</p>';crmp_proof_policy_settings();$same=get_option('crmp_order_proof_same','yes')==='yes';echo '<p><label><input type="checkbox" id="crmp-order-proof-same" name="order_proof_same" value="1" '.checked($same,true,false).'> Use the same fields after order placement as at checkout</label></p><fieldset id="crmp-order-proof-options"'.($same?' disabled hidden':'').'>';crmp_proof_policy_settings('order');echo '</fieldset></section>';
 echo '<section class="crmp-panel"><h2>Email recipients</h2><p><label for="crmp-admin-emails">Admin email(s)</label><input class="large-text" id="crmp-admin-emails" name="admin_emails" value="'.esc_attr($c['admin_emails']).'"></p><p class="description">Used for enabled admin notifications. Separate multiple addresses with commas.</p><p><strong>Customer recipient:</strong> The order billing email address. Each customer receives a separate email.</p></section>';
 echo '<section class="crmp-panel"><h2>Email notifications</h2><p>Choose which notifications to send.</p>';
 foreach(array('admin'=>'Admin notifications','customer'=>'Customer notifications') as $audience=>$title){echo '<h3>'.esc_html($title).'</h3><table class="widefat striped crmp-email-notifications"><thead><tr><th>Notification</th><th>Enabled</th></tr></thead><tbody>';foreach(crmp_email_catalog() as $id=>$type){if($type[1]!==$audience)continue;echo '<tr><td><label for="crmp-enabled-'.esc_attr($id).'">'.esc_html($type[0]).'</label>'.($type[2]==='attention'?'<br><small>Admin alert for interrupted payment reviews.</small>':'').'</td><td><input id="crmp-enabled-'.esc_attr($id).'" type="checkbox" name="enabled['.esc_attr($id).']" value="1" '.checked($c['enabled'][$id],true,false).'></td></tr>';}echo '</tbody></table>';}
 echo '<p><label>Missing-proof reminder delay: <input type="number" name="delay" min="1" max="10080" value="'.absint($c['delay']).'"> minutes after order creation</label></p><p class="description">Send once per order to enabled admin and customer recipients. Only for unpaid manual-payment orders with no proof submitted. Skip if proof arrives or the order is paid, cancelled or refunded. Scheduled sends depend on your site background-task runner. Applies to new orders after enabling this feature.</p><p class="description">Payment verified is optional because WooCommerce can also send Processing or Completed order emails.</p></section>';
 echo '<section class="crmp-panel"><h2>Email customization</h2><p>Edit and preview each email here. Logo, colours and footer inherit your WooCommerce email branding.</p><label for="crmp-email-select"><strong>Select email to customize</strong></label><select id="crmp-email-select" class="widefat">';foreach(crmp_email_catalog() as $id=>$type)echo '<option value="'.esc_attr($id).'" '.selected($id,'customer_rejected',false).'>'.esc_html(ucfirst($type[1]).' — '.$type[0]).'</option>';echo '</select><div class="crmp-email-editor-grid"><div class="crmp-email-editor-fields">';
 foreach(array('subject'=>'Subject','heading'=>'Heading') as $key=>$label)echo '<p><label for="crmp-email-'.esc_attr($key).'">'.esc_html($label).'</label><input id="crmp-email-'.esc_attr($key).'" class="widefat" data-email-field="'.esc_attr($key).'" maxlength="2000"></p>';
 echo '<label for="crmp_email_message">Message</label>';
 wp_editor($c['templates']['customer_rejected']['message'],'crmp_email_message',array('media_buttons'=>false,'teeny'=>true,'quicktags'=>true,'textarea_rows'=>6,'tinymce'=>array('toolbar1'=>'bold italic bullist numlist link unlink undo redo','toolbar2'=>'')));
 echo '<p class="description">Placeholders: {customer_name}, {order_number}, {amount}, {transaction_reference}, {admin_note}, {store_name}</p><fieldset class="crmp-note-highlight"><legend>Reviewer note highlight</legend><label><input type="checkbox" data-email-field="show_note"> Show reviewer note</label><p><label>Highlight label<input class="widefat" data-email-field="note_label" maxlength="2000"></label></p><p>Content source: <code>{admin_note}</code></p><label>Sample reviewer note (preview only)<textarea class="widefat" data-email-field="sample_note" rows="2" maxlength="2000"></textarea></label><p class="description">The actual note comes from the transaction review. If it is empty, the entire highlight is hidden. Sample text is never sent to customers.</p></fieldset>';
 echo '<p><label>Additional text<textarea class="widefat" data-email-field="additional" rows="3" maxlength="20000"></textarea></label></p><p><label>Button text<input class="widefat" data-email-field="button" maxlength="2000"></label></p><button type="button" class="button" id="crmp-email-reset">Restore this template’s defaults</button></div><div class="crmp-email-preview-column"><h3>Email preview</h3><div class="crmp-preview-controls"><button type="button" class="button button-primary" data-preview-width="desktop" aria-pressed="true">Desktop</button> <button type="button" class="button" data-preview-width="mobile" aria-pressed="false">Mobile</button> <button type="button" class="button" id="crmp-refresh-preview">Refresh preview</button></div><p class="description">Preview and test emails use sample data.</p><div class="crmp-preview-frame-wrap"><iframe id="crmp-email-preview" title="Email preview" sandbox=""></iframe></div></div></div><p><label>Test email recipient <input type="email" id="crmp-test-recipient" value="'.esc_attr(wp_get_current_user()->user_email).'"></label> <button type="button" class="button" id="crmp-test-email" disabled>Send test email</button></p><p id="crmp-email-script-status" class="description">Email controls loading. If this message remains, refresh the page or check that browser JavaScript is enabled.</p><p id="crmp-email-feedback" role="status" aria-live="polite"></p></section>';
 submit_button('Save changes','primary','crmp_save_general');echo '</form><p><a class="button" href="'.esc_url(admin_url('admin.php?page=crmp-email-logs')).'">View email logs</a></p></div>';
}
function crmp_email_ajax_authorize(){if(!current_user_can('manage_woocommerce'))wp_send_json_error(array('message'=>'Not allowed.'),403);crmp_require_post();check_ajax_referer('crmp_email_settings','nonce');if(!crmp_email_ready())wp_send_json_error(array('message'=>'Activate WooCommerce before using email controls.'),503);}
add_action('wp_ajax_crmp_email_preview',static function(){
 // phpcs:ignore WordPress.Security.NonceVerification.Missing, WordPress.Security.ValidatedSanitizedInput.InputNotSanitized -- crmp_email_ajax_authorize verifies manager capability, POST and nonce; template JSON is decoded then whitelisted and sanitized by crmp_sanitize_email_template.
 crmp_email_ajax_authorize();$id=sanitize_key(wp_unslash($_POST['template_id']??''));if(!isset(crmp_email_catalog()[$id]))wp_send_json_error(array('message'=>'Invalid email template.'),400);
 // phpcs:ignore WordPress.Security.NonceVerification.Missing, WordPress.Security.ValidatedSanitizedInput.InputNotSanitized -- crmp_email_ajax_authorize verifies manager capability, POST and nonce; template JSON is decoded then whitelisted and sanitized by crmp_sanitize_email_template.
 $raw=isset($_POST['template'])&&is_string($_POST['template'])?json_decode(wp_unslash($_POST['template']),true):array();$template=crmp_sanitize_email_template($id,is_array($raw)?$raw:array());
 // phpcs:ignore WordPress.Security.NonceVerification.Missing, WordPress.Security.ValidatedSanitizedInput.InputNotSanitized -- crmp_email_ajax_authorize verifies manager capability, POST and nonce; template JSON is decoded then whitelisted and sanitized by crmp_sanitize_email_template.
 if(!empty($_POST['reset']))wp_send_json_success(array('template'=>crmp_email_defaults($id)));
 $data=array('customer_name'=>'Alex','order_number'=>'12345','amount'=>'Rs 1,499','transaction_reference'=>'SAMPLE-12345','admin_note'=>$template['sample_note'],'store_name'=>wp_specialchars_decode(get_bloginfo('name'),ENT_QUOTES));
 // Sample URLs are inert in the sandboxed preview; test emails point to the store home only.
 $url=home_url('/');
 // phpcs:ignore WordPress.Security.NonceVerification.Missing, WordPress.Security.ValidatedSanitizedInput.InputNotSanitized -- crmp_email_ajax_authorize verifies manager capability, POST and nonce; template JSON is decoded then whitelisted and sanitized by crmp_sanitize_email_template.
 if(!empty($_POST['send_test'])){
  if(get_transient('crmp_test_email_'.get_current_user_id()))wp_send_json_error(array('message'=>'Please wait 30 seconds before sending another test email.'),429);
 // phpcs:ignore WordPress.Security.NonceVerification.Missing, WordPress.Security.ValidatedSanitizedInput.InputNotSanitized -- crmp_email_ajax_authorize verifies manager capability, POST and nonce; template JSON is decoded then whitelisted and sanitized by crmp_sanitize_email_template.
  $recipient=sanitize_email(wp_unslash($_POST['recipient']??''));if(!is_email($recipient))wp_send_json_error(array('message'=>'Enter a valid test email recipient.'),400);
  set_transient('crmp_test_email_'.get_current_user_id(),1,30);
  $result=crmp_send_logged_test_email($id,$template,$recipient);
  if(is_wp_error($result))wp_send_json_error(array('message'=>$result->get_error_message(),'logUrl'=>admin_url('admin.php?page=crmp-email-logs')),502);
  wp_send_json_success(array('message'=>'Test email sent to the mail server. Inbox delivery is unconfirmed. Check inbox/spam and the Email Logs page.','logUrl'=>admin_url('admin.php?page=crmp-email-logs')));

 }
 $mail=crmp_email_transport();$html=crmp_email_html($id,$template,$data,$url);wp_send_json_success(array('html'=>$mail->style_inline($html)));
});
// phpcs:ignore WordPress.Security.NonceVerification.Missing -- crmp_email_ajax_authorize verifies manager capability, POST and nonce before reading the retry ID.
add_action('wp_ajax_crmp_email_retry',static function(){crmp_email_ajax_authorize();$id=absint($_POST['job_id']??0);global $wpdb;
 // phpcs:ignore WordPress.DB.DirectDatabaseQuery -- Only definite failures can be retried. Accepted or uncertain sending jobs remain immutable.
 $ok=$wpdb->update($wpdb->prefix.'crmp_email_queue',array('status'=>'pending','last_error'=>'','updated_at'=>current_time('mysql',true)),array('id'=>$id,'status'=>'failed','log_hidden'=>0));
 if($ok!==1)wp_send_json_error(array('message'=>'This email cannot be retried. Refresh the delivery log.'),409);
 crmp_email_schedule('crmp_send_email_job',array($id),time()+2);wp_send_json_success(array('message'=>'Failed email queued for retry. Eligibility will be checked again before sending.'));
});
